    98	    private void validateRequest(CheckoutSummaryRequest request) {
    99	        if (request.getItems() == null || request.getItems().isEmpty()) {
   100	            throw new OrderServiceException("INVALID_ORDER", "Cart is empty", HttpStatus.UNPROCESSABLE_ENTITY);
   101	        }
   102	
   103	        Set<String> skus = new HashSet<>();
   104	        for (var item : request.getItems()) {
   105	            if (item.getSku() == null || item.getSku().isEmpty()) {
   106	                throw new OrderServiceException("INVALID_ORDER", "Item SKU is missing", HttpStatus.UNPROCESSABLE_ENTITY);
   107	            }
   108	            if (item.getQuantity() == null || item.getQuantity() <= 0) {
   109	                throw new OrderServiceException("INVALID_ORDER", "Item quantity must be positive", HttpStatus.UNPROCESSABLE_ENTITY);
   110	            }
   111	            if (!skus.add(item.getSku())) {
   112	                throw new OrderServiceException("INVALID_ORDER", "Duplicate SKU in cart", HttpStatus.UNPROCESSABLE_ENTITY);
   113	            }
   114	        }
   115	
   116	        if (request.getCustomer() == null || request.getCustomer().getCpf() == null ||
   117	            request.getCustomer().getCpf().isEmpty() || request.getCustomer().getEmail() == null ||
   118	            request.getCustomer().getEmail().isEmpty()) {
   119	            throw new OrderServiceException("INVALID_ORDER", "Customer CPF and email are required", HttpStatus.UNPROCESSABLE_ENTITY);
   120	        }
   121	
   122	        if (request.getClubTier() == null) {
   123	            throw new OrderServiceException("INVALID_CLUB_TIER", "Club tier is required", HttpStatus.UNPROCESSABLE_ENTITY);
   124	        }
   125	
   126	        if (request.getRegion() == null) {
   127	            throw new OrderServiceException("INVALID_REGION", "Region is required", HttpStatus.UNPROCESSABLE_ENTITY);
   128	        }
   129	
   130	        if (request.getZipCode() == null || request.getZipCode().length() != 8 ||
   131	            !request.getZipCode().matches("\\d{8}")) {
   132	            throw new OrderServiceException("INVALID_ZIP_CODE", "Invalid ZIP code", HttpStatus.UNPROCESSABLE_ENTITY);
   133	        }
   134	
   135	        if (request.getShippingMethod() == null) {
   136	            throw new OrderServiceException("INVALID_SHIPPING_METHOD", "Shipping method is required", HttpStatus.UNPROCESSABLE_ENTITY);
   137	        }
   138	
   139	        if (request.getPaymentMethod() == null) {
   140	            throw new OrderServiceException("INVALID_PAYMENT_METHOD", "Payment method is required", HttpStatus.UNPROCESSABLE_ENTITY);
   141	        }
   142	
   143	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
   144	        if (installments < 1 || installments > 12) {
   145	            throw new OrderServiceException("INVALID_INSTALLMENTS", "Invalid number of installments", HttpStatus.UNPROCESSABLE_ENTITY);
   146	        }
   147	
   148	        if (request.getPaymentMethod() == PaymentMethod.PIX || request.getPaymentMethod() == PaymentMethod.BANK_SLIP) {
   149	            if (installments != 1) {
   150	                throw new OrderServiceException("INVALID_INSTALLMENTS", "PIX and BANK_SLIP do not support installments", HttpStatus.UNPROCESSABLE_ENTITY);
   151	            }
   152	        }
   153	    }
   154	
   155	    private List<Product> getAndValidateProducts(List<CheckoutSummaryRequest.OrderItemRequest> items) {
   156	        List<Product> products = new ArrayList<>();
   157	
   158	        for (var item : items) {
   159	            Optional<Product> product = productRepository.findById(item.getSku());
   160	
   161	            if (product.isEmpty()) {
   162	                throw new OrderServiceException("UNKNOWN_PRODUCT", "Product not found: " + item.getSku(), HttpStatus.UNPROCESSABLE_ENTITY);
   163	            }
   164	
   165	            if (product.get().getDiscontinued()) {
   166	                throw new OrderServiceException("PRODUCT_DISCONTINUED", "Product is discontinued: " + item.getSku(), HttpStatus.UNPROCESSABLE_ENTITY);
   167	            }
   168	
   169	            if (product.get().getStock() < item.getQuantity()) {
   170	                throw new OrderServiceException("INSUFFICIENT_STOCK", "Insufficient stock for: " + item.getSku(), HttpStatus.UNPROCESSABLE_ENTITY);
   171	            }
   172	
   173	            products.add(product.get());
   174	        }
   175	
   176	        return products;
   177	    }
   178	
   179	    private BigDecimal calculateProductsSubtotal(List<CheckoutSummaryRequest.OrderItemRequest> items,
   180	                                                  List<Product> products) {
   181	        BigDecimal subtotal = BigDecimal.ZERO;
   182	
   183	        for (int i = 0; i < items.size(); i++) {
   184	            BigDecimal itemTotal = CurrencyUtils.multiply(
   185	                    products.get(i).getPrice(),
   186	                    new BigDecimal(items.get(i).getQuantity())
   187	            );
   188	            subtotal = CurrencyUtils.add(subtotal, itemTotal);
   189	        }
   190	
   191	        return subtotal;
   192	    }
   193	
   194	    private void validateCoupon(String coupon, List<CheckoutSummaryRequest.OrderItemRequest> items,
   195	                                List<Product> products) {
   196	        if (coupon == null || coupon.isEmpty()) {
   197	            return;
   198	        }
   199	
   200	        if (!isValidCoupon(coupon)) {
   201	            throw new OrderServiceException("INVALID_COUPON", "Coupon not found: " + coupon, HttpStatus.UNPROCESSABLE_ENTITY);
   202	        }
   203	    }
   204	
   205	    private boolean isValidCoupon(String coupon) {
   206	        return "WELCOME10".equals(coupon) || "MINUS50".equals(coupon) ||
   207	               "FREESHIPPING".equals(coupon) || "BUY3PAY2".equals(coupon);
   208	    }
   209	
   210	    private BigDecimal calculateCouponDiscount(String coupon,
   211	                                               List<CheckoutSummaryRequest.OrderItemRequest> items,
   212	                                               List<Product> products, BigDecimal productsSubtotal,
   213	                                               String cpf) {
   214	        if (coupon == null || coupon.isEmpty()) {
   215	            return BigDecimal.ZERO;
   216	        }
   217	
   218	        BigDecimal discount = BigDecimal.ZERO;
   219	
   220	        if ("WELCOME10".equals(coupon)) {
   221	            discount = CurrencyUtils.multiply(productsSubtotal, new BigDecimal("0.10"));
   222	        } else if ("MINUS50".equals(coupon)) {
   223	            if (productsSubtotal.compareTo(new BigDecimal("300.00")) < 0) {
   224	                throw new OrderServiceException("COUPON_NOT_APPLICABLE", "Coupon not applicable", HttpStatus.UNPROCESSABLE_ENTITY);
   225	            }
   226	            discount = new BigDecimal("50.00");
   227	        } else if ("FREESHIPPING".equals(coupon)) {
   228	            throw new OrderServiceException("COUPON_NOT_APPLICABLE", "FREESHIPPING can only be applied during shipping calculation", HttpStatus.UNPROCESSABLE_ENTITY);
   229	        } else if ("BUY3PAY2".equals(coupon)) {
   230	            discount = calculateBuy3Pay2Discount(items, products);
   231	        }
   232	
   233	        BigDecimal maxDiscount = CurrencyUtils.multiply(productsSubtotal, COUPON_MAX_PERCENT);
   234	        if (discount.compareTo(maxDiscount) > 0) {
   235	            discount = maxDiscount;
   236	        }
   237	
   238	        return discount;
   239	    }
   240	
   241	    private BigDecimal calculateBuy3Pay2Discount(List<CheckoutSummaryRequest.OrderItemRequest> items,
   242	                                                 List<Product> products) {
   243	        BigDecimal discount = BigDecimal.ZERO;
   244	
   245	        for (int i = 0; i < items.size(); i++) {
   246	            long quantity = items.get(i).getQuantity();
   247	            long freeItems = quantity / 3;
   248	            if (freeItems > 0) {
   249	                BigDecimal itemDiscount = CurrencyUtils.multiply(
   250	                        products.get(i).getPrice(),
   251	                        new BigDecimal(freeItems)
   252	                );
   253	                discount = CurrencyUtils.add(discount, itemDiscount);
   254	            }
   255	        }
   256	
   257	        return discount;
   258	    }
   259	
   260	    private ShippingInfo calculateShipping(ShippingMethod method, String zipCode,
   261	                                          List<CheckoutSummaryRequest.OrderItemRequest> items,
   262	                                          List<Product> products, Region region) {
   263	        BigDecimal totalWeight = calculateTotalWeight(items, products);
   264	
   265	        if (method == ShippingMethod.COURIER) {
   266	            if (totalWeight.compareTo(new BigDecimal(MAX_COURIER_WEIGHT_KG)) > 0) {
   267	                throw new OrderServiceException("SHIPPING_METHOD_UNAVAILABLE", "Courier does not support this weight", HttpStatus.UNPROCESSABLE_ENTITY);
   268	            }
   269	            return new ShippingInfo(COURIER_COST, COURIER_DELIVERY_DAYS);
   270	        } else if (method == ShippingMethod.STORE_PICKUP) {
   271	            return new ShippingInfo(BigDecimal.ZERO, STORE_PICKUP_DAYS);
   272	        } else if (method == ShippingMethod.ECONOMY || method == ShippingMethod.EXPRESS) {
   273	            String service = method == ShippingMethod.ECONOMY ? "STD" : "EXP";
   274	            int weightGrams = totalWeight.multiply(new BigDecimal("1000"))
   275	                    .setScale(0, RoundingMode.DOWN).intValue();
   276	
   277	            Optional<TransLogClient.TransLogQuoteResponse> quote = transLogClient.getQuote(zipCode, weightGrams, service);
   278	
   279	            if (quote.isEmpty()) {
   280	                throw new OrderServiceException("SHIPPING_METHOD_UNAVAILABLE",
   281	                        "Shipping method not available for this location", HttpStatus.UNPROCESSABLE_ENTITY);
   282	            }
   283	
   284	            TransLogClient.TransLogQuoteResponse response = quote.get();
   285	            BigDecimal cost = new BigDecimal(response.getPriceCents()).divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
   286	            int days = (int) Math.ceil(response.getEtaHours() / 24.0);
   287	
   288	            if (region == Region.NORTH) {
   289	                days += NORTH_EXTRA_DAYS;
   290	            } else if (region == Region.NORTHEAST) {
   291	                days += NORTHEAST_EXTRA_DAYS;
   292	            }
   293	
   294	            return new ShippingInfo(cost, days);
   295	        }
   296	
   297	        throw new OrderServiceException("INVALID_SHIPPING_METHOD", "Invalid shipping method", HttpStatus.UNPROCESSABLE_ENTITY);
   298	    }
   299	
   300	    private BigDecimal calculateTotalWeight(List<CheckoutSummaryRequest.OrderItemRequest> items,
   301	                                           List<Product> products) {
   302	        BigDecimal totalWeight = BigDecimal.ZERO;
   303	
   304	        for (int i = 0; i < items.size(); i++) {
   305	            BigDecimal itemWeight = products.get(i).getWeightKg()
   306	                    .multiply(new BigDecimal(items.get(i).getQuantity()));
   307	            totalWeight = totalWeight.add(itemWeight);
   308	        }
   309	
   310	        return totalWeight;
   311	    }
   312	
   313	    private BigDecimal calculateInsurance(BigDecimal productsSubtotal, Region region) {
   314	        BigDecimal percentage;
   315	        BigDecimal limit = null;
   316	
   317	        switch (region) {
   318	            case SOUTHEAST, SOUTH -> percentage = new BigDecimal("0.01");
   319	            case MIDWEST -> percentage = new BigDecimal("0.015");
   320	            case NORTH -> {
   321	                percentage = new BigDecimal("0.025");
   322	                limit = new BigDecimal("30.00");
   323	            }
   324	            case NORTHEAST -> {
   325	                percentage = new BigDecimal("0.02");
   326	                limit = new BigDecimal("30.00");
   327	            }
   328	            default -> percentage = BigDecimal.ZERO;
   329	        }
   330	
   331	        BigDecimal insurance = CurrencyUtils.multiply(productsSubtotal, percentage);
   332	
   333	        if (limit != null && insurance.compareTo(limit) > 0) {
   334	            insurance = limit;
   335	        }
   336	
   337	        return insurance;
   338	    }
   339	
   340	    private BigDecimal calculatePaymentAdjustment(BigDecimal subtotal, PaymentMethod method, Integer installments) {
   341	        int numInstallments = installments != null ? installments : 1;
   342	
   343	        if (method == PaymentMethod.PIX) {
   344	            return CurrencyUtils.multiply(subtotal, PIX_DISCOUNT_PERCENT.negate());
   345	        } else if (method == PaymentMethod.BANK_SLIP) {
   346	            return BANK_SLIP_FEE;
   347	        } else if (method == PaymentMethod.CREDIT_CARD) {
   348	            if (numInstallments <= 3) {
   349	                return BigDecimal.ZERO;
   350	            }
   351	            BigDecimal monthlyRate = new BigDecimal("0.0199");
   352	            BigDecimal numerator = monthlyRate;
   353	            BigDecimal denominator = BigDecimal.ONE.subtract(
   354	                    BigDecimal.ONE.add(monthlyRate).pow(-numInstallments)
   355	            );
   356	            BigDecimal installmentValue = subtotal.multiply(numerator.divide(denominator, 10, RoundingMode.HALF_EVEN));
   357	            installmentValue = CurrencyUtils.roundToCents(installmentValue);
   358	            BigDecimal totalValue = installmentValue.multiply(new BigDecimal(numInstallments));
   359	            return CurrencyUtils.subtract(totalValue, subtotal);
   360	        }
   361	
   362	        return BigDecimal.ZERO;
   363	    }
   364	
   365	    private BigDecimal calculateInstallmentAmount(BigDecimal total, Integer installments) {
   366	        int numInstallments = installments != null && installments > 0 ? installments : 1;
   367	        return CurrencyUtils.divide(total, new BigDecimal(numInstallments));
   368	    }
   369	
   370	    private BigDecimal calculateNextPurchaseCredit(ClubTier tier, BigDecimal productsSubtotal) {
   371	        if (tier == ClubTier.BRONZE) {
   372	            return BigDecimal.ZERO;
   373	        } else if (tier == ClubTier.SILVER) {
   374	            return CurrencyUtils.multiply(productsSubtotal, new BigDecimal("0.02"));
   375	        } else if (tier == ClubTier.GOLD) {
   376	            return CurrencyUtils.multiply(productsSubtotal, new BigDecimal("0.05"));
   377	        }
   378	
   379	        return BigDecimal.ZERO;
   380	    }
   381	
   382	    private static class ShippingInfo {
   383	        BigDecimal cost;
   384	        Integer days;
   385	
   386	        ShippingInfo(BigDecimal cost, Integer days) {
   387	            this.cost = cost;
   388	            this.days = days;
   389	        }
   390	    }
   391	}

